export const meta = {
  name: 'audit-resolved-todos',
  description: 'Audit pending GSD todos to find ones already resolved by recent phases/PRs but never archived',
  phases: [
    { title: 'Verify', detail: 'one agent per todo checks current main tree for whether the problem still exists' },
    { title: 'Confirm', detail: 'adversarial re-check of any todo flagged resolved/partial — try to prove it is still open' },
  ],
}

const TODOS = args
const RECENT = "#538 (split/dedup oversized source files in fuse/sdk-core/api/web), #541 (feat(api): API CID and provider hardening with unpin module dedup), #543 (FUSE and IPNS write-path durability hardening), #544 (IPNS signed-record verify coverage chokepoint + non-CAS sequence gate), #548 (Kubo v0.42 upgrade + raise ipfs cpu/mem + persist Provide.Strategy roots)"

const VERDICT_SCHEMA = {
  type: 'object',
  required: ['title', 'status', 'confidence', 'evidence'],
  additionalProperties: false,
  properties: {
    title: { type: 'string', description: 'short title of the todo' },
    status: { type: 'string', enum: ['resolved', 'partial', 'open'] },
    confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
    evidence: { type: 'string', description: 'concrete grounding: file:line showing the fix is present (or absent), and/or the commit/PR that did it' },
    residual: { type: 'string', description: 'if partial/open: exactly what still remains to do; empty if fully resolved' },
    likely_pr: { type: 'string', description: 'the PR number that resolved it, if identifiable; else empty' },
  },
}

const CONFIRM_SCHEMA = {
  type: 'object',
  required: ['agrees_resolved', 'rebuttal'],
  additionalProperties: false,
  properties: {
    agrees_resolved: { type: 'boolean', description: 'true only if you independently confirm EVERY part of the todo action is done in the current tree' },
    rebuttal: { type: 'string', description: 'if false: the residual part of the problem that still exists, with file:line evidence' },
  },
}

const verifyPrompt = (file) => `You are auditing ONE GSD todo to determine if it has ALREADY been resolved by recent work but was never moved to .planning/todos/completed/.

Repo root: /Users/myankelev/Code/random/cipher-box — you are on branch main, fully up to date.
Todo file: .planning/todos/pending/${file}

Steps:
1. Read the todo file fully. Identify the precise problem/defect/action it describes and every file it references.
2. Inspect the CURRENT state of every referenced file (Read the exact lines/symbols named). Determine whether the described problem still exists in the current tree right now.
3. Correlate with git history: run \`git log --oneline -15 -- <referenced-file>\` and \`git log -S '<distinctive symbol or string from the todo>' --oneline -10\` to see if a recent commit/PR already addressed it. Recent potentially-relevant merged PRs: ${RECENT}.
4. Decide status:
   - "resolved": the described problem is FULLY fixed / the action is FULLY done in the current tree. REQUIRES concrete evidence — cite file:line showing the fix and/or the commit/PR.
   - "partial": some done, some remains. Put what remains in "residual".
   - "open": still needs doing. This is the default whenever you are not certain.

Be conservative: if you cannot find concrete evidence the fix is present, return "open". Never guess — a wrongly-archived open todo is worse than keeping a resolved one around. Note: pure feature-request todos (new capabilities not yet built) are almost always "open".

Return the structured verdict (title = a short label for this todo).`

const confirmPrompt = (file, v) => `A first-pass audit claims this GSD todo is ALREADY ${v.status.toUpperCase()}: ${file} — "${v.title}".
First-pass evidence: ${v.evidence}
First-pass residual (if any): ${v.residual || '(none)'}

Your job is ADVERSARIAL: try to REFUTE the claim. Independently inspect the current main tree and hunt for ANY part of the described problem that STILL EXISTS.

Repo root: /Users/myankelev/Code/random/cipher-box (branch main).
Read the todo yourself: .planning/todos/pending/${file}. Then Read the referenced files and check the exact symbols/lines.

- If the problem genuinely still exists in whole or part, set agrees_resolved=false and describe the residual defect with file:line evidence.
- Set agrees_resolved=true ONLY if you independently confirm every part of the todo's action is done in the current tree.
- Default to agrees_resolved=false when uncertain.`

const results = await pipeline(
  TODOS,
  (file) => agent(verifyPrompt(file), { label: `verify:${file.slice(11, 44)}`, phase: 'Verify', schema: VERDICT_SCHEMA })
    .then(v => ({ ...v, file })),
  (v, file) => {
    if (!v || v.status === 'error') return { file, status: 'error', title: file }
    if (v.status === 'resolved' || v.status === 'partial') {
      return agent(confirmPrompt(file, v), { label: `confirm:${file.slice(11, 44)}`, phase: 'Confirm', schema: CONFIRM_SCHEMA })
        .then(c => ({ ...v, confirm: c }))
        .catch(() => ({ ...v, confirm: null }))
    }
    return { ...v, confirm: null }
  }
)

return results.filter(Boolean)

